module jt51_acc ( clk, zero, op31_acc, rl, op_out, ne, noise, left, right, 
        xleft, xright );
  input [1:0] rl;
  input [13:0] op_out;
  input [9:0] noise;
  output [15:0] left;
  output [15:0] right;
  output [15:0] xleft;
  output [15:0] xright;
  input clk, zero, op31_acc, ne;
  wire   zero_out, n1;
  wire   [13:0] op_value;
  wire   [1:0] rl_out;
  wire   [9:0] left_man;
  wire   [2:0] left_exp;
  wire   [9:0] right_man;
  wire   [2:0] right_exp;

  jt51_sum_op_1 u_left ( .clk(clk), .zero(zero_out), .en_ch(rl_out[0]), 
        .op_out(op_value), .out(xleft) );
